subtasks.details:
Add Gradle dependencies for PostgreSQL (JDBC driver), MinIO (AWS S3 SDK), MeiliSearch (Java client), AWS SES (AWS SDK v2), JWT (`io.jsonwebtoken:jjwt-api`), and password hashing (`spring-boot-starter-security` for BCrypt/Argon2).
<info added on 2025-07-31T10:50:21.717Z>
The project's build script will be updated from the Kotlin DSL (`build.gradle.kts`) to the Groovy DSL (`build.gradle`).

Modify `build.gradle` to include the following dependencies:

```groovy
plugins {
    id 'org.springframework.boot' version '3.2.5'
    id 'io.spring.dependency-management' version '1.1.4'
    id 'org.jetbrains.kotlin.jvm' version '1.9.23'
    id 'org.jetbrains.kotlin.plugin.spring' version '1.9.23'
}

group = 'com.example'
version = '0.0.1-SNAPSHOT'

java {
    sourceCompatibility = '21'
}

repositories {
    mavenCentral()
}

dependencyManagement {
    imports {
        mavenBom "software.amazon.awssdk:bom:2.25.31"
    }
}

dependencies {
    // Core Spring Boot
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    implementation 'com.fasterxml.jackson.module:jackson-module-kotlin'
    implementation 'org.jetbrains.kotlin:kotlin-reflect'

    // Security (Password Hashing & JWT)
    implementation 'org.springframework.boot:spring-boot-starter-security'
    implementation 'io.jsonwebtoken:jjwt-api:0.12.5'
    runtimeOnly 'io.jsonwebtoken:jjwt-impl:0.12.5'
    runtimeOnly 'io.jsonwebtoken:jjwt-jackson:0.12.5'

    // Database
    runtimeOnly 'org.postgresql:postgresql'

    // Search
    implementation 'com.meilisearch.sdk:meilisearch-java:0.12.0'

    // AWS SDKs for MinIO (S3) and SES
    implementation 'software.amazon.awssdk:s3'
    implementation 'software.amazon.awssdk:sesv2'

    // Testing
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testImplementation 'org.springframework.security:spring-security-test'
}

tasks.withType(org.jetbrains.kotlin.gradle.tasks.KotlinCompile) {
    kotlinOptions {
        freeCompilerArgs += '-Xjsr305=strict'
        jvmTarget = '21'
    }
}

tasks.withType(Test) {
    useJUnitPlatform()
}
```
</info added on 2025-07-31T10:50:21.717Z>
